INSERT INTO `abilities` (`ability_id`, `ability_url`, `ability_file`, `ability_name`, `ability_description`, `ability_type`, `ability_cooldown`) VALUES
(1, 'https://static.wikia.nocookie.net/allstartd/images/5/5d/120_Potential_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240202125743', '120_Potential_Ability_Icon.webp', '120 Potential', 'Upon activation , a cutscene plays , where the Cursed Brothers have unlocked 120% of their potential. This ability gives Cursed Brothers a permanent damage increase of 5.66 million , which does not stack with level.', 'Self Buff', 'infinite'),
(2, 'https://www.google.com/url?sa=i&url=https%3A%2F%2Fwww.denofgeek.com%2Ftv%2Fattack-on-titan-season-3-episode-9-review-ruler-of-the-walls%2F&psig=AOvVaw2IdUVxhBgguLxrczt6YAGY&ust=1739968130368000&source=images&cd=vfe&opi=89978449&ved=0CBQQjRxqFwoTCKjI_8eczYsDFQAAAAAdAAAAABAE', 'attack_on_titan_309-1.webp', 'Abnormal Giant (Burns)', 'Upon activation , it will 4x the unit -  damage in burn to all enemies on her range. Summons a Titan with 110B.', 'Damage Over Time / Summon', '720'),
(3, 'https://static.wikia.nocookie.net/allstartd/images/5/54/Ikki_Potent_%28Awakening_Awkening_Abilty_Icon.png/revision/latest/scale-to-width-down/92?cb=20221227155449', 'Ikki_Potent8Awakening_Awkening_Abilty_Icon.webp', 'Awakening', 'At Ikki Potent (Awaken) -  last upgrade , he gains an ability called \"Awakening. This boosts his damage by 1 ,568 ,627.38 , increases his range by 30 , slightly narrows his AoE Cone and allows changes him to an air type unit. However , there is a toll , which is that Ikki Potent (Awaken) cannot hit ground enemies.\nActivating the ability again will turn off this ability and revert his stats to normal at max upgrade.', 'Attack Change', '15'),
(4, 'https://static.wikia.nocookie.net/allstartd/images/b/b9/Annihilation_Type_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240320073226', 'Annihilation_Type_Ability_Icon.webp', 'Annihilation Type', 'Upon activation , Patternine (Serious) will use Annihilation Type , dealing x5.5 his current damage to all enemies in his range. This ability has a cooldown of 80 seconds and does not have a global cooldown.', 'Instant Damage', '80'),
(5, 'https://static.wikia.nocookie.net/allstartd/images/b/b1/Arez_Ability_Icon.png/revision/latest?cb=20240320120253', 'Arez_Ability_Icon.webp', 'Arez', 'Upon activation , Bunny Enthusiast deals 170 Million Damage to every enemy within his range. This ability has a global cooldown of 300 seconds.', 'Instant Damage', '330'),
(6, 'https://static.wikia.nocookie.net/allstartd/images/d/de/The_Patriot_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20220520015901', 'The_Patriot_Ability_Icon.webp', 'Armor Bus', 'When clicked , The Patriot will activate Love Train , pushing enemies away from the base and preventing enemies from reaching it for about 25 seconds. The cooldown of this move is global.', 'Base Protection', '600'),
(7, 'https://static.wikia.nocookie.net/allstartd/images/0/08/ArmoredGiant%28Defense%29.png/revision/latest?cb=20240129173318', 'ArmoredGiant29.webp', 'Armored Giant (Defense)', 'Summons a Titan with 234 ,66M hp.', 'Heal / Summon', '60'),
(8, 'https://static.wikia.nocookie.net/allstartd/images/1/1b/Atomic_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20231209092856', 'Atomic_Ability_Icon.webp', 'Atomic', 'When activated it plays a cutscene and deals current damage to all enemies within its range (doesnt affect bleed). This doesn’t have a global cooldown.', 'Instant Damage', '300'),
(9, 'https://static.wikia.nocookie.net/allstartd/images/b/b6/Atomic_All_Range_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20231209092922', 'Atomic_All_Range_Ability_Icon.webp', 'Atomic: All Range', 'When activated it plays a cutscene and deals 6 billion damage to all enemies on the map. This ability has an unknown global cooldown that share with The Pharoah so you can only use one of them per game.', 'Nuke', 'infinite'),
(10, 'https://static.wikia.nocookie.net/allstartd/images/d/d5/AttackGiant%28Rewinds%29.png/revision/latest?cb=20240129173212', 'AttackGiant29.webp', 'Attack Giant (Rewinds)', 'Summons a Titan with 95M hp.', 'Rewind, Summon', '40'),
(11, 'https://static.wikia.nocookie.net/allstartd/images/e/e2/Awakening_Ascended_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20240206071840', 'Awakening_Ascended_Ability_Icon.webp', 'Awakening: Ascended', 'Upon activation , Awakening: Ascended will play a cutscene where Koku awakens into his Instinctive form and makes all enemies take 15% more damage similarly to Idol -  ability. He will now also obtain the Critical effect , dealing 3x damage on every third hit Koku does. This ability lasts for 4 minutes.', 'Buff / Critical', '900'),
(12, 'https://static.wikia.nocookie.net/allstartd/images/9/9c/Awakening_Nuke_Ability_Icon.png/revision/latest?cb=20240206072014', 'Awakening_Nuke_Ability_Icon.webp', 'Awakening: Nuke', 'Upon activation , a cutscene will play and will do ~13.5 billion damage to all enemies on the map. This ability can only be used once. However , Koku (Instinctive) must charge the ability to 100% by taking down a certain amount of enemies before the ability can be used.', 'Nuke', 'infinite'),
(13, 'https://images.vexels.com/media/users/3/130326/isolated/preview/02585af1c38561d33cebbb49f9d2009c-fire-flame-icon-silhouette.png', 'burning-skull.png', 'Blackflames', 'Black Flames causes an affected enemy to take damage every 2 seconds for 40 seconds in total (20 ticks).', 'Damage Over Time', 'on hit'),
(14, 'https://cdn-icons-png.flaticon.com/512/205/205916.png', 'barbed-arrow.png', 'Bleed', 'Bleed causes an affected enemy to take damage every 2 seconds for 8 seconds in total (4 ticks).', 'Damage Over Time', 'on hit'),
(15, 'https://static.wikia.nocookie.net/allstartd/images/6/65/Blizzard_icon.png/revision/latest?cb=20220312231945', 'Blizzard_icon.webp', 'Blizzard', 'Deals 85M damage to all enemies on the map and applies an Ultimate Timestop. Blizzard has a global cooldowm of 400 seconds(6 minutes and 40 seconds)', 'Instant Damage', '400'),
(16, 'https://static.wikia.nocookie.net/allstartd/images/5/5b/Blood-Moon_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20230616054548', 'Blood-Moon_Ability_Icon.webp', 'Blood Moon', 'At Falcon (Eclipse) -  last upgrade , he gains an ability called \"Blood-Moon. This boosts ALL D.O.T (Damage Over Time) effects by 2x for 300 seconds (5 minutes) and shows a cutscene of Griffith awakening the Egg of Kings.', 'Buff', '600'),
(17, 'https://static.wikia.nocookie.net/allstartd/images/8/81/Blood_Queen_Orb.png/revision/latest/scale-to-width-down/78?cb=20240522105350', 'Blood_Queen_Orb.webp', 'BloodLust', 'This passive only activates when Blood Queen (B-Kui) is upgraded to the 7th level and equipped with the Blood Queen Orb.\nBloodLust adds final damage to Blood Queen (B-Kui) that is not shown in the unit -  stats. The damage is based on the base HP:\n\n2.222B damage added to the unit if base HP is greater than 9 billion.\n734M damage added to the unit if base HP is greater than 3.5 billion.\n446M damage added to the unit if base HP is greater than 500 million.', 'Self Buff', 'passive'),
(18, 'https://static.wikia.nocookie.net/allstartd/images/4/49/Book_Time_Rewind.png/revision/latest/scale-to-width-down/80?cb=20221226142921', 'Book_Time_Rewind.webp', 'Book: Time Rewind', 'Upon activating , a cutscene will play , showing Julian -  grimoire above him , while rewinding all enemies in his range to their position from 12 seconds ago. This ability has a cooldown of 8 minutes.', 'Rewind', '480'),
(19, 'https://static.wikia.nocookie.net/allstartd/images/6/6c/Buff_Ability_Icon.png/revision/latest/scale-to-width-down/80?cb=20230424073946', 'Buff_Ability_Icon.webp', 'Buff Ability', 'When activated. he buffs all units in his range by 250% damage and 20% range boost. The buff ability has a cooldown of 60 seconds and lasts for 30 seconds.', 'Buff', '60'),
(20, 'https://images.freeimages.com/fic/images/icons/1262/amora/256/burn.png', 'flaming-arrow.png', 'Burn', 'Burn causes an affected enemy to take damage every 2 seconds for 12 seconds in total (6 ticks).', 'Damage Over Time', '0'),
(21, 'https://static.wikia.nocookie.net/allstartd/images/7/7f/Candybeam_Icon.png/revision/latest/scale-to-width-down/100?cb=20230710022601', 'Candybeam_Icon.webp', 'Candy Beam', 'Upon activation , Boo stuns all enemies in his range for 7 seconds.', 'Stun', '45'),
(22, 'https://static.wikia.nocookie.net/allstartd/images/f/f2/CartGiant%28Money%29.png/revision/latest?cb=20240129172959', 'CartGiant29.webp', 'Cart Giant (Money)', 'Summons a titan with 18k hp.', 'Income / Summon', '30'),
(23, 'https://static.wikia.nocookie.net/allstartd/images/1/1e/ColossalGiant%28Nuke%29.png/revision/latest?cb=20240129173632', 'ColossalGiant29.webp', 'Colossal Giant (Nuke)', 'Upon activation , it will deal 3 ,5B damage to all enemies. Summons a Titan with 134B.', 'Summon / Instant Damage', '500'),
(24, 'https://static.wikia.nocookie.net/allstartd/images/1/12/Compass_Needle_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240320073211', 'Compass_Needle_Ability_Icon.webp', 'Compass Needle', 'Upon activation , Patternine (Serious) gains 720 ,000 damage for 42 seconds. This ability does not stack with levels and has a cooldown of 160 seconds.', 'Self Buff', '160'),
(25, 'https://preview.redd.it/what-does-this-kurama-with-susanoo-armor-mode-called-v0-g0bavktddgpd1.png?width=474&format=png&auto=webp&s=dce4d0f09e181fda282988084927f347c71a7ae2', 'what-does-this-kurama-with-susanoo-armor-mode-called-v0-g0bavktddgpd1.webp', 'Control', 'Beast Spawner is a 7-star ground and Full AoE type controllable unit based on the Majestic Attire: Susanoo Kurama from Naruto Shippuden. Similar to Kovegu (Alternative) and Veguko , he requires Zaruto (SS) and Kosuke (SS) to be placed (with the Controlled beast variant and Controlled samurai variant orbs). In order to obtain Beast Spawner , you need to get the Samurai and Beast variants from the Star Pass (Tier 100) and equip the Samurai variant to Kosuke (SS) , and the beast variant to Zaruto (SS).', 'Special', '470'),
(26, 'https://static.wikia.nocookie.net/allstartd/images/a/ac/Corruption_Ability.png/revision/latest?cb=20230516210143', 'Corruption_Ability.webp', 'Corruption', 'When activated , half of God Black Fusion (Alternative) -  body will become corrupted and he will gain 1 ,000 ,000 more damage. He will no longer change enemy enchant. This is a permanent change and has an infinite cooldown.', 'Self Buff', 'infinite'),
(27, 'https://cdn4.iconfinder.com/data/icons/shooter-game-2/64/Artboard_19-512.png', 'targeting.png', 'Critical A', 'Every 4th attack , The unit does an attack which deals 4x his base damage.', 'Critical', 'passive'),
(28, 'https://cdn4.iconfinder.com/data/icons/shooter-game-2/64/Artboard_19-512.png', 'targeting.png', 'Critical B', 'Every 2 attacks , the unit does an attack which deals 3x his base damage.', 'Critical', 'passive'),
(29, 'https://cdn4.iconfinder.com/data/icons/shooter-game-2/64/Artboard_19-512.png', 'targeting.png', 'Critical C', 'Every 3 attacks , the unit does an attack which deals 3x his base damage.', 'Critical', 'passive'),
(30, 'https://static.wikia.nocookie.net/allstartd/images/5/57/Darkness_Flame_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240630043330', 'Darkness_Flame_Ability_Icon.webp', 'Darkness Flame', 'When activated , a short cutscene referencing the YuYu Hakusho anime will play out. Summoning the Dragon of the Darkness Flame , Evil Shade (Final) deals 12.5B damage and applies Stoke effect on all enemies on the map. This ability has a cooldown of 720 seconds.\nStatus effect \"Stoke\" increases burn-related status effects such as Burn and Black Flames damage by 1.5x.', 'Instant Damage, Special', '720'),
(31, 'https://static.wikia.nocookie.net/allstartd/images/c/c2/Decay_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20230927004024', 'Decay_Ability_Icon.webp', 'Decay', 'Upon activation , all enemies within his range will take ~0.6% of total hp every second until they reach 65% of their max hp. It only affects non-boss enemies that are above 65% of their health.', 'Damage by %', '240'),
(32, 'https://static.wikia.nocookie.net/allstartd/images/f/f9/Devil_Domain_Ability_Icon.png/revision/latest?cb=20240623052825', 'Devil_Domain_Ability_Icon.webp', 'Devil Domain', 'Upon activation , a short cutscene referencing the Jujutsu Kaisen anime will play out. During Sukuna -  Expansion , known as Malevolent Shrine , it deals 3% of Sukuna -  damage every 0.5 seconds , while also chipping away 0.25% of his damage from your base. The ability continually inflicts damage until the base health is depleted or until the player deactivates the ability by clicking again. This ability has a cooldown of 5 seconds , no global cooldown , and scales with buffs.', 'Special', '1'),
(33, 'https://static.wikia.nocookie.net/allstartd/images/c/c9/Disintegration_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20230424090244', 'Disintegration_Ability_Icon.webp', 'Disintegration', 'At Wrathdioas (Demon King) 7th upgrade , he gains an ability called \"Disintegration\". This ability sets enemies to 40% of their health (This only affects enemies in his current range) , if they are above 40%. This ability does not stack with God Black Fusion.', 'Damage by %', '45'),
(34, 'https://static.wikia.nocookie.net/allstartd/images/1/12/Mysterious_X_%28VOID%29_Manual_ability.png/revision/latest/scale-to-width-down/92?cb=20220520011227', 'Mysterious_X_29_Manual_ability.webp', 'Domain 9', 'A nearly identical skill to Domain. This skill stops all enemies within an 83 range radius for 5.7 seconds. Enemies will gain immunity to all stun/freeze type skills for 5 seconds after being affected by this.', 'Stun', '90'),
(35, 'https://static.wikia.nocookie.net/allstartd/images/0/0c/Domain_Of_Perfection_Ability_Icon.png/revision/latest?cb=20240510142933', 'Domain_Of_Perfection_Ability_Icon.webp', 'Domain of Perfection', 'Upon activation , Patchface (Transfigured) activates his Domain Expansion , touching the souls of a Boss/Mini-Boss in range and converting them into transfigured enemies , which are portrayed as clones similar to Eyezen (Final) -  \"Hypnosis Takeover\". This ability can only be used on BOSSES/MINIBOSSES and will pick ONLY 1 Boss/Mini-Boss , and clone it (1 per path). All summoned units have 20% of that Boss/Mini-Boss -  current health , with a health cap of 5 ,000 ,000 ,000 (5 billion) HP. This ability can only be used once. This ability also has INFINITE GLOBAL COOLDOWN that is shared with Eyezen (Final)', 'Summon', 'infinite'),
(36, 'https://static.wikia.nocookie.net/allstartd/images/0/03/Dowsing_Hook_Ability_Icon.png/revision/latest/scale-to-width-down/90?cb=20240323000024', 'Dowsing_Hook_Ability_Icon.webp', 'Dowsing Hook', 'Increases Chain Avenger (Enraged) damage by around 11.6M damage for 120 second with a 600 second cooldown', 'Self Buff', '600'),
(37, 'https://static.wikia.nocookie.net/allstartd/images/1/1f/Dragon_Absorption_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240630043314', 'Dragon_Absorption_Ability_Icon.webp', 'Dragon Absorption', 'Upon activation , Evil Shade (Final) gains a permanent 7 ,500 ,000 damage added to his original damage and now inflicts Black Flames with every attack. This shares an infinite global cooldown with Vegu (Ego Ascension) and Tatsu (Rainbow Flames).', 'Self Buff', 'infinite'),
(38, 'https://static.wikia.nocookie.net/allstartd/images/b/bc/Draw_Card_Ability_Icon.png/revision/latest?cb=20230424052002', 'Draw_Card_Ability_Icon.webp', 'Draw Card', 'Draw card is a manual ability of Yugi with 40 uses and a cooldown of 20 seconds. Initially you need use this ability which draws a random card from your deck , with the aim of drawing one of the five different Exodia cards (Body , Left Arm , Right Arm , Left Leg , Right Leg). If you draw an Exodia card , it appears permanently on display behind Yugi. Once you draw the fifth and last Exodia card , a cutscene will play , and Yugi deals exactly 5B damage to all enemies on the map , including air units.', 'Nuke', '20'),
(39, 'https://static.wikia.nocookie.net/allstartd/images/7/74/Earring_Fusion_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20240515112431', 'Earring_Fusion_Ability_Icon.webp', 'Earring Fusion', 'When activated , Khalifa (Supa) and Legendary Kel perform a fusion dance and fuse into Kelfu.', 'Special', 'infinite'),
(40, 'https://static.wikia.nocookie.net/allstartd/images/c/cb/Ability_Eat_The_Dirt.png/revision/latest/scale-to-width-down/80?cb=20220926092656', 'Ability_Eat_The_Dirt.webp', 'Eat The Dirt', 'This is the ability that appears only when the Reset Orb is equipped. When Eat The Dirt is activated , it reset the other unit -  manual ability cooldowns , but it doesnt affect global cooldowns such as The Patriot , ZIO (ASCENDED) , Red Servant (Final) , The Pharaoh (after Exodia has been used) , and Demon Lord.\nFor example , 3 players place 24 Kura (Darkness) (with orb equipped) total , Use them all , then player 4 can use Eat The Dirt and all Kura (Darkness) have their Write Names back , effectively doubling the damage in the same timeframe!\n\nNOTE: Bites the Dust cant be used to reset Bites the Dust. Youll have to wait for the cooldown.', 'Special', '1000'),
(41, 'https://static.wikia.nocookie.net/allstartd/images/1/1f/Holy_Enchant_Icon.png/revision/latest?cb=20220225072739', 'spiral-arrow.png', 'Enchant Weak', 'Attacking a mob with this units makes the mob replacing its enchant by the weak enchant for the unit , ONLY if it already has a enchant.', 'Enchant Change', 'on hit'),
(42, 'https://static.wikia.nocookie.net/allstartd/images/c/c3/Energy_Bomba_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240206071716', 'Energy_Bomba_Ability_Icon.webp', 'Energy Bomba: 100%', 'Energy Bomba is a Special Ability that can only be activated once it -  fully charged. If you try to activate it before it hits 100% , the ability will not do anything to the enemies and it will go on cooldown for a few seconds. To increase the percentage , this unit has to kill enemies. Every 5 enemies increases the percentage by 1% , taking around 500 kills to reach 100%. When activated , the ability deals 10 billion damage to all units in the map.\nEven though the % shown in the icon can be exceed 100% , the damage dealt by the ability is still capped at 10 billion. This ability has a global cooldown that does not affect Stampede (???%) -  Reality Destruction or Ombre -  Atomic: All Range global cooldown , but it does affect The Pharaoh -  ability.', 'Nuke', 'infinite'),
(43, 'https://static.wikia.nocookie.net/allstartd/images/3/3d/Enuma_Reduction_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20240224101347', 'Enuma_Reduction_Ability_Icon.webp', 'Enuma Reduction', 'Upon activation , this sets the all enemies on the map to 25% of their MAX hp. Stacks with God Black Fusion -  Wall Of Light/Wrathdioas (Demon King) -  Disintegration/Ruffy (5th Form) -  Fifth Form Gun/Future T & Aqua Vegu -  Hope Execution/The Strongest In History -  Waffle Maker , etc. It has an infinite global cooldown , and thus can only be used once.', 'Nuke by %', 'infinite'),
(44, 'https://static.wikia.nocookie.net/allstartd/images/f/f6/Erased.png/revision/latest/scale-to-width-down/92?cb=20231118061337', 'Erased.webp', 'Erased', 'When activated , a cutscene showing a glitchy pink flash flashes three times across the screen , followed with a red and black explosion. This sets all enemies (every single one on the map) to 65% of their max health (if they are above 65% of their health) and timestops them for 15 seconds while also teleporting them back to the last 3 corners they passed.\nUnits affected by this ability will not be able to be affected by it again , and the ability has a global cooldown , however , selling and using it again/using Yoshikage Kira -  Eat The Dirt and using the ability again will teleport the enemies back 3 corners again , but there will be no global timestop.', 'Damage by % / Golden Stun / Teleport', '320'),
(45, 'https://static.wikia.nocookie.net/allstartd/images/d/d1/Stampede_%28XXX%25%29_Esper_Rage_Icon.png/revision/latest/scale-to-width-down/92?cb=20230424050223', 'StampedeEsper_Rage_Icon.webp', 'Esper Rage', 'When activated , it plays a cutscene and deals 7.5 billion damage to all units on the map. The cooldown is 8 minutes , it has a global cooldown as Yoshaga Kiryu (Eat The Dirt) -  ability does not affect its cooldown. The global cooldown is unknown but it is more than the ability cooldown. You cant use this ability 2 times with a friend.', 'Nuke', '480'),
(46, 'https://static.wikia.nocookie.net/allstartd/images/f/fd/Experimental_Splash_Ability_Icon.png/revision/latest?cb=20240320085546', 'Experimental_Splash_Ability_Icon.webp', 'Experimental Splash', 'Upon activation , all units within Research Captain -  AoE (Circle) will be slowed and inflicted with the Virus effect. This ability has a cooldown of 120 seconds.\n\nThe Virus effect makes units 25% more potent to enchant damage. This means instead of taking 3x damage , enemies affected by the Virus will take 3.75x more damage than usual , if they face an enchant disadvantage. This effect does not apply to enemies without an enchant disadvantage or without an enchant at all.', 'Buff', '120'),
(47, 'https://static.wikia.nocookie.net/allstartd/images/a/ab/Fairy_Sphere_Ability_Icon.png/revision/latest?cb=20240507113000', 'Fairy_Sphere_Ability_Icon.webp', 'Fairy Sphere', 'Upon activation , enemies will be prevented from walking into the base for 35 seconds. This ability is a one-time use.', 'Base Protection', 'infinite'),
(48, 'https://static.wikia.nocookie.net/allstartd/images/2/2e/FallOfMan.png/revision/latest/scale-to-width-down/100?cb=20240519121914', 'FallOfMan.webp', 'Fall Of Man', 'Upon activation of this ability , all enemies on the map like Powerful 1/2 , Decelerate , Cloner , Regenerate , Elemental , Rage , and Armored (except for Air , Miniboss , and Boss enemies) turns into regular enemies. Additionally , Air enemies on the map that are affected by the ability will be targetable by ground units. This ability has a cooldown of 400 seconds (6 minutes and 40 seconds). But has a global cooldown for a bit longer to around 8 minutes , or approximately 480-500 seconds.', 'Reveal', '500'),
(49, 'https://static.wikia.nocookie.net/allstartd/images/e/e6/Fear.png/revision/latest/scale-to-width-down/100?cb=20240523083827', 'Fear.webp', 'Fear', 'Fear causes an affected enemy to take 10% additional damage. And makes Enemies walk backward faster when rewinded with the amount being 4x faster on 1x speed , 3x faster on 2x speed , and 2x faster on 3x speed. Fear last for 16 seconds before disappearing.', 'Special', 'passive'),
(50, 'https://static.wikia.nocookie.net/allstartd/images/6/60/FemaleGiant%28Stops%29.png/revision/latest?cb=20240129173520', 'FemaleGiant29.webp', 'Female Giant (Stops)', 'Upon activation , it will ultimate time stop all enemies for 40 seconds. Summons a Titan with 30 ,7B hp.', 'Golden Stun / Summon', '400'),
(51, 'https://mangamegamart.com/cdn/shop/files/S061c8fba78334f4da34563bba067b368A.webp?v=1706659301&width=1445', 'S061c8fba78334f4da34563bba067b368A.webp', 'Fifth Form Gun', 'When activated it plays a cutscene and deals 25% damage of an enemies current health to all enemies within the map. This effect is theorised to have a global cooldown of 960 seconds (16 minutes).', 'Damage by %', '480'),
(52, 'https://static.wikia.nocookie.net/allstartd/images/6/62/Finaldomain.png/revision/latest?cb=20231108014733', 'Finaldomain.webp', 'Final Domain Finisher', 'Upon Activation , Mysterious X will use the full extent of his limitless abilities , to time stop the ENTIRE map for 1 MINUTE and deal 7.5B damage to ALL enemies on the map. This ability can be reused , both the time stop , and the nuke. Final Domain Finisher has a GLOBAL cooldown of 8 minutes , or 480 seconds.', 'Golden Stun, Instant Damage', '480'),
(53, 'https://static.wikia.nocookie.net/allstartd/images/f/f9/Yama-east.png/revision/latest?cb=20231017005522', 'Yama-east.webp', 'Fire Path', 'East (3rd Upgrade)\nUpon activation Old Will (B-Kui) -  attack type changes to AoE (Cone) , his damage will change to 16 ,300 ,000  , his range changes to 100 , his SPA changes to 3.5 , he does not burn , and he cannot hit airs.\n\n\nWest (3rd Upgrade)\nUpon activation Old Will (B-Kui) -  attack type changes to AoE (Full) , his damage will change to 11 ,000 ,000 , his range changes to 100 , his SPA changes to 5 , he inflicts burn , and he gains the ability to hit air enemies.\n\n\nSouth (3rd Upgrade)\nUpon activation Old Will (B-Kui) turns into a summoner unit , summoning skeletons scaling with his current dmg on the map every 45 seconds. When defeated , the skeletons will explode and inflict burn damage to surrounding enemies.\n\n\nNorth (3rd Upgrade)\nUpon activation Old Will (B-Kui) -  attack type changes to a 55 degree AoE (Cone) , his damage will change to 21 ,900 ,000 , his range changes to 150 , his SPA changes to 15 , he inflicts burn , and he cannot hit airs.', 'Summon, Attack Change', '15'),
(54, 'https://static.wikia.nocookie.net/allstartd/images/6/6d/Flare_Stop_Ability_Icon.png/revision/latest?cb=20240601234704', 'Flare_Stop_Ability_Icon.webp', 'Flare Stop', 'Upon activation , Flare Lord (Serious) will use his Space-Time Manipulation Ultimate Skills , time stopping all enemies in his range for 8 seconds. This ability has a cooldown of 40 seconds.', 'Stun', '40'),
(55, 'https://static.wikia.nocookie.net/allstartd/images/f/f0/Flashy_Finale_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240202125802', 'Flashy_Finale_Ability_Icon.webp', 'Flashy Finale', 'Upon activation , a cutscene featuring Todo -  Black Flash plays. This ability damages every enemy on the map for 2.5x their current damage stat , scales with buff and enchants , and has a cooldown of 400 seconds.', 'Instant Damage', '400'),
(56, 'https://static.wikia.nocookie.net/allstartd/images/f/f9/FlyingGiant.png/revision/latest?cb=20240129173423', 'FlyingGiant.webp', 'Flying Giant', 'Summons a Titan with 20 ,7B hp that hit only airs.', 'Summon', '60'),
(57, 'https://cdn-icons-png.flaticon.com/512/3778/3778994.png', 'frozen-arrow.png', 'Freeze', 'Freezing causes an affected enemy to stop completely. Freezing comes with a toll , as a frozen enemy cannot be affected by timestops or rewinds.  Can\"t be reapplied for 10 seconds.', 'Stun', 'on hit'),
(58, 'https://static.wikia.nocookie.net/allstartd/images/7/72/FV_Ability_Icon.png/revision/latest?cb=20230424074020', 'FV_Ability_Icon.webp', 'FV Ability', 'When activated , he prevents enemies from walking past a certain point near the base for 30 seconds , pushing them back if they do pass it , similarly to the The Patriot -  Amor Bus ability.', 'Base Protection', '600'),
(59, 'https://cdn3.vectorstock.com/i/1000x1000/76/87/gale-wind-icon-vector-39587687.jpg', 'frostfire.png', 'Gale Slow', 'GaleSlow temporarily reduces the movement speed of the enemy hit by 30% for 8 seconds. This ability can be stacked with slowed enemies , causing a speed reduction total of 65%. However it cannot be stacked with Sunburn.', 'Slow', 'on hit'),
(60, 'https://static.wikia.nocookie.net/allstartd/images/c/c6/Global_Zero.png/revision/latest?cb=20220423034108', 'Global_Zero.webp', 'Global: Zero', 'This ability only appears when the Envy Orb is equipped. Upon activation of this ability , a cutscene plays. During the cutscene , all enemies on the map are rewinded for 12 seconds. The distance enemies are rewinded depends on how fast they are going. This ability does not have a global cooldown and has a cooldown of 510 seconds.', 'Rewind / Slow', '510'),
(61, 'https://static.wikia.nocookie.net/allstartd/images/3/3b/Hakai_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20231108065355', 'Hakai_Ability_Icon.webp', 'Hakai', 'Upon activation , Hakai deals 2 billion damage to enemies within his range. It has a cooldown of 8 minutes (480 seconds) , but is able to be used again with another unit. It is not affected by any buffs.', 'Instant Damage', '480'),
(62, 'https://static.wikia.nocookie.net/allstartd/images/d/d8/Heavenly_Impact_Ability.png/revision/latest?cb=20240206093138', 'Heavenly_Impact_Ability.webp', 'Heavenly Impact', 'Upon activation , a cutscene will play and will do 1.3 billion damage to all enemies within his range.', 'Instant Damage', '360'),
(63, 'https://cdn-icons-png.flaticon.com/512/15532/15532672.png', 'cheerful.png', 'HitHeal', 'Whenever Speedaholic (Enchanted) deals damage to enemies , that damage also heals Base HP for the same amount.', 'Heal', 'on hit'),
(64, 'https://static.wikia.nocookie.net/allstartd/images/9/9b/Holy_Hook_Ability_Icon.png/revision/latest/scale-to-width-down/90?cb=20240322235954', 'Holy_Hook_Ability_Icon.webp', 'Holy Hook', 'Heals the base for an additional 2.5x of the current Chain Avenger (Enraged) damage with a 600 second cooldown.', 'Heal', '600'),
(65, 'https://static.wikia.nocookie.net/allstartd/images/4/44/Yaef.png/revision/latest/scale-to-width-down/92?cb=20231016225624', 'Yaef.webp', 'Holy Selection', 'Upon activation , all units in the map even outside The Almighty -  range will receive a +300% (4x) damage buff and a 20% range buff for 60 seconds. The cooldown of this ability is also 60 seconds , meaning that a permanent buff can be achieved through auto-activation', 'Buff', '60'),
(66, 'https://static.wikia.nocookie.net/allstartd/images/3/3f/Hope_Execution_Ability_Icon.png/revision/latest?cb=20240420031744', 'Hope_Execution_Ability_Icon.webp', 'Hope Execution', 'Upon activation , all enemies on the map under 10% HP will be insta-killed. Unlike Chain Avenger (Enraged) , this ability has no 100 billion HP cap. This ability is a one-time use.', 'Nuke by %', 'infinite'),
(67, 'https://static.wikia.nocookie.net/allstartd/images/0/01/Hypnosis_Reverse_Ability_Icon.png/revision/latest?cb=20240829222955', 'Hypnosis_Reverse_Ability_Icon.webp', 'Hypnosis Reverse', 'Upon activation , Eyezen will rewind all enemies within his range back to the position they were 12 seconds ago. This ability has a cooldown of 80 seconds. Unit affected by this ability cannot be affected by it again.', 'Rewind', '80'),
(68, 'https://static.wikia.nocookie.net/allstartd/images/2/26/Hypnosis_Takeover_Ability_Icon.png/revision/latest?cb=20240829222955', 'Hypnosis_Takeover_Ability_Icon.webp', 'Hypnosis Takeover', 'When activated , he copies enemies and summon them as troops that quicker than Metal Freezer -  self clone ability. He can only summon up to 10 units at once. All summoned units have a half of the current of that enemy -  health , not from the maxed health of the enemy. The health of unit that summons is based on which enemy is up front. This ability can only be used once.', 'Summon', 'infinite'),
(69, 'https://static.wikia.nocookie.net/allstartd/images/e/e4/Incomplete_Shrine_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240703053042', 'Incomplete_Shrine_Ability_Icon.webp', 'Incomplete Shrine', 'The Strongest In History applies burn to all enemies on the map , causing them to take 2.5B damage every second for 7 seconds in total (7 ticks) , dealing 17.5B damage in total for a price of 750M damage to players base.\nThis ability has a cooldown of approximately 720 seconds (12 minutes) , but it can only be used once.', 'Nuke', 'infinite'),
(70, 'https://static.wikia.nocookie.net/allstartd/images/8/82/Infinite_Karma_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20231026215234', 'Infinite_Karma_Ability_Icon.webp', 'Infinite Karma', 'This is the ability that appears only when the Emotions Orb is equipped. When you activate Infinite Karma , Hatred Demon will deploy another 4 dragons. Rage Dragon , Tree Dragon , Tree Leaf Dragon and Crazed Dragon', 'Special', 'infinite'),
(71, 'https://static.wikia.nocookie.net/allstartd/images/b/b3/Instant_Spirit_Buff_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240510143017', 'Instant_Spirit_Buff_Ability_Icon.webp', 'Instant Spirit Buff', 'Upon activation , Patchface (Transfigured) finds the true essence of his soul , buffing his overall power and adding a permanent 30 ,240 ,000 damage to his current damage. This ability has infinite global cooldown that share same global cooldown with Eyepatch (Serious) -  Ultra Swap and Tatsu (Rainbow Flames) -  Rainbow Flame Surge .', 'Self Buff', 'infinite'),
(72, 'https://static.wikia.nocookie.net/allstartd/images/5/57/Instinctual_Destruction_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240703054047', 'Instinctual_Destruction_Ability_Icon.webp', 'Instinctual Destruction', 'Upon activation , a cutscene will play and half of your base -  HP will be removed. The removed HP is added to the base nuke of 9 billion. The total damage caps at 15 billion. This ability shares a GLOBAL cooldown with Ombre -  Atomic: All Range ability and Stampede (???%) -  Esper Rage ability..', 'Nuke', 'infinite'),
(73, 'https://static.wikia.nocookie.net/shingekinokyojin/images/d/da/Jaw_Titan_%28Anime%29_character_image_%28Porco_Galliard%29.png/revision/latest?cb=20201220224328', 'Jaw_Titan_29_character_image_29.webp', 'Jaw Giant (Bleeds)', 'Upon activation , it will apply bleed to all enemies on her range. Summons a Titan with 2 ,4M hp.', 'Damage Over Time / Summon', '800'),
(74, 'https://static.wikia.nocookie.net/allstartd/images/7/76/Judgement_Hook_Ability_Icon.png/revision/latest/scale-to-width-down/90?cb=20240323000048', 'Judgement_Hook_Ability_Icon.webp', 'Judgement Hook', 'Kills all enemies within his range that have 10% or lower HP , their HP need to be less than 100 billion. Otherwise he will deal 100B damage instead. This ability is a one time use per game.', 'Nuke', 'infinite'),
(75, 'https://i1.sndcdn.com/artworks-JJQzyS80LgWMfYZl-yzzykQ-t1080x1080.jpg', 'artworks-JJQzyS80LgWMfYZl-yzzykQ-t1080x1080.jpg', 'Liberation', 'Upon activation a timer for 5 seconds starts. Dying within that time frame it will revive you and push the enemies 4 paths backwards. This ability can only be used once.', 'Teleport', 'infinite'),
(76, 'https://static.wikia.nocookie.net/allstartd/images/0/07/Love_Love%21_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20230811004613', 'Love_Love21_Ability_Icon.webp', 'Love Love!', 'This ability works only when any variants of Ruffy is placed on the map. When Love Love! is activated , a cutscene plays and she timestops all enemies over the entire map for a very long 45 seconds. The global cooldown of this ability is shared with ZIO (ASCENDED) , Jokato Koju (ASCENDED) , and Devil (he will only teleport 3 corners and reduce the hp of the enemy , but without the timestop).', 'Golden Stun', '400'),
(77, 'https://static.wikia.nocookie.net/allstartd/images/c/c1/Magic_Trap_Ability_Icon.png/revision/latest?cb=20240620145006', 'Magic_Trap_Ability_Icon.webp', 'Magic Trap', 'Upon activation , Masked Trapper places a trap on the track near him , damaging enemies who walk on it equal to their HP. The traps have HP equal to Masked Trapper -  current damage stat. Multiple traps may be placed on one spot , and traps can be placed in different areas by controlling Masked Trapper. walking to another path and activating his ability there. This ability has a cooldown of 20 seconds , and the traps despawn after one minute.', 'Trap', '20'),
(78, 'https://static.wikia.nocookie.net/allstartd/images/e/e5/Meditation_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20240308064047', 'Meditation_Ability_Icon.webp', 'Meditation A', 'Upon activation , Universe Justice #1 (Serious) will stop attacking and start his meditation. His Ki Focus will raise by 1 per wave (with a max of 10). When activated another time after a cooldown of 180 seconds , his damage will raise depending on the Ki Focus he gained. When Meditation is activated a second time while he has 1-5 Ki Focus , he will gain 430 ,000 damage for every point. When Meditation is activated a second time while he has 6-10 Ki Focus , he will gain 822 ,000 damage for every point (regardless of level) for the next 600 seconds.', 'Self Buff', '180'),
(79, 'https://static.wikia.nocookie.net/allstartd/images/e/e9/Menacing_Steps_Ability_Icon.png/revision/latest?cb=20240424062144', 'Menacing_Steps_Ability_Icon.webp', 'Menacing Steps', 'When this ability is used , French Crusader (Requiem) will time stop all enemies on the map for 10 seconds , and set a total 25 enemies speed to 1 within his range. This ability has an infinite GLOBAL cooldown.\n\nNote: Setting the enemies -  speed to 1 means that the enemies -  speed will be decreased to their speed in wave 1.', 'Slow', 'infinite'),
(80, 'https://static.wikia.nocookie.net/allstartd/images/5/5c/Meteor_Strikes_v2_Ability_Icon.png/revision/latest?cb=20240223054802', 'Meteor_Strikes_v2_Ability_Icon.webp', 'Meteor Strike V2', 'Upon activation , Blinding Luster summons a shower of meteors , dealing 2.5x his current damage to every enemy within his range. This ability has a global cooldown of 440 seconds.', 'Instant Damage', '440'),
(81, 'https://static.wikia.nocookie.net/allstartd/images/0/0b/Minidomain.png/revision/latest?cb=20231108014707', 'Minidomain.webp', 'Mini Domain', 'Mysterious X (Final) has a manual ability that allows him to timestop all enemies in his range for 8 seconds. The larger his range is , the more reach his time stop has.', 'Stun', '45'),
(82, 'https://i.scdn.co/image/ab67616d0000b2736f45a37dcb112a49ccbb3f5d', 'ab67616d0000b2736f45a37dcb112a49ccbb3f5d.jpg', 'Multiple Abilities', 'Activating each of these abilities will change Worl (Vigilante) -  type of attack , with Q: Whip stunning enemies , Q: Smoke slows , Q: Float can only hit air enemies , and Q: Energy changes his attack to a Cone AoE , all of these are removed when upgrading Worl (Vigilante) to upgrade 6.', 'Attack Change', '15'),
(83, 'https://static.wikia.nocookie.net/allstartd/images/e/ee/Path_Orb.png/revision/latest/scale-to-width-down/80?cb=20211124022620', 'Path_Orb.webp', 'Multiple Paths', 'Summoning multiple units , the character can use different powers : nature enchant transform , bleed , burn , base heal , gale slow , hit airs.', 'Special', 'passive'),
(84, 'https://static.wikia.nocookie.net/allstartd/images/d/dd/Brook_Music_Activation.jpg/revision/latest/scale-to-width-down/92?cb=20220212104246', 'Brook_Music_Activation.webp', 'Music', 'Skeleton (Artist) can play music on his activation , and the song can be selected using a Sound ID list.\nWhen his skill is activated , his and other units damage is increased by his current damage (capped at 250% and range increased by 25%.\n\nNote: To hear music , you must turn up the music in the game settings , attack effects must be on , and the Audio ID must be valid.', 'Buff', '60'),
(85, 'https://static.wikia.nocookie.net/allstartd/images/f/f1/Needle_Trap_Ability_Icon.png/revision/latest?cb=20240321012843', 'Needle_Trap_Ability_Icon.webp', 'Needle Trap', 'Upon activation , Upper Fraud places a trap made out of spikes on the track near him , damaging enemies who walk on it equal to their HP. If destroyed , the trap will inflict poison on the enemy , in total dealing x7 the trap -  remaining damage. The spikes are always level 1 and do not gain HP with Upper Fraud -  Level. Multiple spikes may be placed on one spot , and spikes can be placed in different areas by controlling Upper Fraud , walking to another path and activating his ability there. This ability has a cooldown of 90 seconds , and the traps despawn after 450 seconds (unconfirmed).', 'Trap', '90'),
(86, 'https://static.wikia.nocookie.net/allstartd/images/7/7e/Numb_Breath_Ability_Icon.png/revision/latest?cb=20240408075451', 'Numb_Breath_Ability_Icon.webp', 'Numb Breath', '(TAKE THIS WITH A GRAIN OF SALT , INFORMATION IS NOT CONFIRMED) When activated , all enemies on the map will be invisibly debuffed , making all stuns last for 3.5x longer than usual (7 seconds). This ability has a global cooldown of three minutes.', 'Stun', '180'),
(87, 'https://static.wikia.nocookie.net/allstartd/images/7/74/Origami_Battlefield.png/revision/latest/scale-to-width-down/92?cb=20231017203817', 'Origami_Battlefield.webp', 'Origami Battlefield', 'When clicked , Paper Beauty (Goddess) deals 3x her current damage to all units in her range.', 'Instant Damage', '300'),
(88, 'https://static.wikia.nocookie.net/allstartd/images/e/e1/Passive_Transfiguration_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240510142949', 'Passive_Transfiguration_Ability_Icon.webp', 'Passive Transfiguration', 'Upon activation , Patchface (Transfigured) will use Idle Transfiguration , and heal your base (7.5B HP Heal). This ability shares a infinite global cooldown with Boo (Kid) -  Sleep Ability.', 'Heal', 'infinite'),
(89, 'https://static.wikia.nocookie.net/allstartd/images/3/34/PawPawAbilityTyrant.png/revision/latest/scale-to-width-down/92?cb=20231215070341', 'PawPawAbilityTyrant.webp', 'Paw Paw', 'Similarly to Dr. Heart -  Replacement , Tyrant sends up to 4 enemies back to the last corner. Using the Paw Orb , the PawPaw ability can teleport up to 15 enemies max instead of 4.', 'Teleport', '45'),
(90, 'https://static.wikia.nocookie.net/allstartd/images/2/29/Zazashi_%28PERFECTION%29_PERFECT_BLUE-WARRIOR_Icon.png/revision/latest/scale-to-width-down/92?cb=20220520015643', 'Zazashi_29_PERFECT_BLUE-WARRIOR_Icon.webp', 'Perfect Blue-Warrior', 'When clicked , Zazashi (PERFECTION) summons his Susano-o. This can be controlled by whoever owns the Kakashi. This can only be used once , as any other attempt to summon the Susano-o will not do anything , similar to Meta-Knight -  Lance Mech.', 'Special', '470'),
(91, 'https://cdn-icons-png.freepik.com/512/238/238299.png', 'chemical-arrow.png', 'Poison', 'Poison causes an affected enemy to take damage every 3.5 seconds for 21 seconds in total (6 ticks).', 'Damage Over Time', 'on hit'),
(92, 'https://i.scdn.co/image/ab67616d0000b2736f45a37dcb112a49ccbb3f5d', 'ab67616d0000b2736f45a37dcb112a49ccbb3f5d.jpg', 'Q: Faux', 'When activated , Worl buffs all units within his range by 200% as well as buffing their range by 20% , this ability lasts for 30 seconds with a cooldown of 60 seconds.', 'Buff', '60'),
(93, 'https://static.wikia.nocookie.net/allstartd/images/1/16/Whitestache_%28Prime%29_Quake_Shatter.png/revision/latest/scale-to-width-down/80?cb=20220716200632', 'Whitestache_29_Quake_Shatter.webp', 'Quake Shatter', 'When clicked , Whitestache (Prime) \"cracks\" the air and creates 2 huge tsunamis. This will damage every unit in his range that will do 3x of his current damage and summons 3 tsunamis which damages and will do 1.15x or 15% more DMG of his current damage.', 'Instant Damage', '120'),
(94, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEhcU-DSUXc37693GHQbEjjhKO5gPv3OjYnw&s', 'mighty-force.png', 'Raging Escanor', 'Gains an additionnal 193 000 damage for 22 waves. (4246000)', 'Raging', 'each wave'),
(95, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEhcU-DSUXc37693GHQbEjjhKO5gPv3OjYnw&s', 'mighty-force.png', 'Raging Gohan', 'Gains an additionnal 387000 damage each wave for 12 waves (4644000).', 'Raging', 'each wave'),
(96, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEhcU-DSUXc37693GHQbEjjhKO5gPv3OjYnw&s', 'mighty-force.png', 'Raging Guy', 'Gains an additionnal 156853 damage per wave , but deals 1000 base HP damage.', 'Raging', 'each wave'),
(97, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEhcU-DSUXc37693GHQbEjjhKO5gPv3OjYnw&s', 'mighty-force.png', 'Raging Nanami', 'Gains an additionnal 108 000 damage for 11 waves. (1 118 000)', 'Raging', 'each wave'),
(98, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSEhcU-DSUXc37693GHQbEjjhKO5gPv3OjYnw&s', 'mighty-force.png', 'Raging Vegeta', 'Gains an additionnal 1260000 damage per waves and deals 233420 base health damage ,every wave for 43 waves (54000000).', 'Raging', 'each wave'),
(99, 'https://static.wikia.nocookie.net/allstartd/images/7/77/Rainbow_Flame_Surge_Ability_Icon.png/revision/latest?cb=20240522100352', 'Rainbow_Flame_Surge_Ability_Icon.webp', 'Rainbow Flame Surge', 'Similar to Eyepatch (Serious) -  , this ability permanently increases Tatsu (Rainbow Flames) final damage by 7 ,344 ,000. This ability has an infinite global cooldown that is shared with Eyepatch (Serious) -  Ultra Swap , Patchface (Transfigured) -  Instant Spirit Buff and Evil Shade (Final) -  Dragon Absorption.', 'Self Buff', 'infinite'),
(100, 'https://static.wikia.nocookie.net/allstartd/images/7/70/RANGE-BOOSTER-ON.png/revision/latest?cb=20211218115835', 'RANGE-BOOSTER-ON.webp', 'Range Booster', 'A similar skill to Shinzou Wo Sasageyo. As the name suggests , this ability will increase the range of units within Flower Magus -  range by 30%. However , unlike the damage buff , this does NOT stack with itself.', 'Buff', '60'),
(101, 'https://static.wikia.nocookie.net/allstartd/images/c/c6/Regrowth_Ability_Icon.png/revision/latest?cb=20240418045327', 'Regrowth_Ability_Icon.webp', 'Regrowth', 'Upon activation , this ability heals the base for 750 million health at level while refreshing all ability cooldowns. Has a cooldown of roughly 17 minutes (1020 seconds).', 'Special', '1020'),
(102, 'https://static.wikia.nocookie.net/allstartd/images/9/9d/Replacement_II_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20231127095859', 'Replacement_II_Ability_Icon .webp', 'Replacement II', 'When acticated , Dr. Heart (Mystical) create a transparent blue sphere where the first enemy is and all enemies inside sphere get teleported to the last corner that they turned. He is able to teleport up to 18 enemies.', 'Teleport', '50'),
(103, 'https://cdn-icons-png.freepik.com/512/4334/4334094.png', 'william-tell-skull.png', 'Rupture', 'Rupture causes an affected enemy to take damage every 2 seconds for 24 seconds in total (12 ticks).', 'Damage Over Time', 'on hit'),
(104, 'https://static.wikia.nocookie.net/allstartd/images/f/f1/Sai_Boost%21_Ability_Icon.png/revision/latest?cb=20240628015650', 'Sai_Boost21_Ability_Icon.webp', 'Sai Boost', 'Upon activation , Future Demon King (Unlocked) will permanently give himself 30 million damage. The ability is a one time use , having an infinite cooldown.', 'Self Buff', 'infinite'),
(105, 'https://static.wikia.nocookie.net/allstartd/images/7/7f/SeikaClone_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20230914033951', 'SeikaClone_Ability_Icon.webp', 'SeikaClone', 'Exorcist (DemonLord) summons one out of three demon servants from the base. The demon servant that is summoned is completely reliant on RNG. Centipede is the slowest demon servant with 137.5 million HP , Satori which has 110 million HP , and ElectroMonster which has 25 million HP , is the fastest of the summonable servants and stuns upon death. Multiple servants are summoned on maps with multiple paths , one for each path. The ability has a 45 second cooldown.', 'Summon', '45'),
(106, 'https://static.wikia.nocookie.net/allstartd/images/7/77/Self_Clone.png/revision/latest/scale-to-width-down/80?cb=20220928082117', 'Self_Clone.webp', 'Self Clone', 'When clicked , the unit summons a clone with 22 million hp (DOES NOT SCALE WITH LEVEL , scale with unit DAMAGE) , and has a cooldown of 45 seconds.', 'Summon', 'infinite'),
(107, 'https://static.wikia.nocookie.net/allstartd/images/2/29/Senbon_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240528103600', 'Senbon_Ability_Icon.webp', 'Senbon', 'Upon activation , all units in The Fear (Volt) -  range will be inflicted with bleed damage , each tick dealing around 4.8x of his current damage. This ability has a global cooldown of 480 seconds.', 'Instant Damage', '480'),
(108, 'https://static.wikia.nocookie.net/allstartd/images/2/2a/Shine.png/revision/latest/scale-to-width-down/80?cb=20230516080425', 'Shine.webp', 'Shine', 'Upon activation , the damage of all units in Idol -  range will be buffed by a certain percentage represented by her damage stat (capped at 250%). The buff lasts for 60 seconds and the cooldown of the ability is 60 seconds , meaning that a near-perfect autobuff can be achieved using the auto-activate button.', 'Buff', '60'),
(109, 'https://static.wikia.nocookie.net/allstartd/images/4/4a/Onwin_Shinzou_Icon.png/revision/latest?cb=20211218105705', 'Onwin_Shinzou_Icon.webp', 'Shinzou o Sasageyo', 'All towers in the range of Onwin get their damage boosted by his current damage. The effect stacks with other Damage Buffs!', 'Buff', '60'),
(110, 'https://static.wikia.nocookie.net/allstartd/images/c/c8/Silent_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20231127095923', 'Silent_Ability_Icon.webp', 'Silent', 'Upon activation of this ability , all enemies within his range like Powerful 1/2 , Decelerate , Cloner , Regenerate , Elemental , Rage , and Steadfast (except for Air , Armored , Miniboss , and Boss enemies) turns into regular enemies.', 'Reveal', '480'),
(111, 'https://static.wikia.nocookie.net/allstartd/images/6/68/SleepIcon.png/revision/latest/scale-to-width-down/100?cb=20230710022722', 'SleepIcon.webp', 'Sleep', 'When activated , Boo adds an extra 5 billion HP to the base. This ability has an infinite global cooldown and cannot be spammed.', 'Heal', 'infinite'),
(112, 'https://static.thenounproject.com/png/460769-200.png', 'achilles-heel.png', 'Slow', 'Slow permanently lowers the movement speed of the enemy hit by 50% , making it a very powerful and meta-defining ability.', 'Slow', 'on hit'),
(113, 'https://static.wikia.nocookie.net/allstartd/images/3/37/Special_Expansion_Ability_Icon.png/revision/latest?cb=20240321005145', 'Special_Expansion_Ability_Icon.webp', 'Special Expension', 'Upon activation , a cutscene will play and will do 75 million damage to all enemies on the map. This ability has a global cooldown of 180 seconds , which is tied to Bunny Girl.', 'Instant Damage', '180');
INSERT INTO `abilities` (`ability_id`, `ability_url`, `ability_file`, `ability_name`, `ability_description`, `ability_type`, `ability_cooldown`) VALUES
(114, 'https://static.wikia.nocookie.net/allstartd/images/6/69/Spell_Stop_Ability_Icon.png/revision/latest?cb=20240414114014', 'Spell_Stop_Ability_Icon.webp', 'Spell Stop', 'Upon activation , Kurumi will summon and explode a large clock , applying Slow to all units in her range and timestopping them for 6.5 seconds. This ability has a cooldown of 40 seconds.', 'Stun / Slow', '40'),
(115, 'https://static.wikia.nocookie.net/allstartd/images/1/14/Spirit_Fission_Ability_Icon.png/revision/latest?cb=20240703054003', 'Spirit_Fission_Ability_Icon.webp', 'Spirit Fission', 'Upon activation of this ability , all enemy types within his range (Powerful 1/2 , Decelerate , Regenerate , Elemental , and Rage , excluding Air , Miniboss , and Boss enemies) turn into regular enemies. However , unlike DemonLord Waifu and Dr. Heart (Mystical) , he cant turn Cloners into regular enemies.\n300 second global cooldown.', 'Reveal', '300'),
(116, 'https://static.wikia.nocookie.net/allstartd/images/4/46/Spirit_Nuke_Ability_Icon.png/revision/latest?cb=20240513105414', 'Spirit_Nuke_Ability_Icon.webp', 'Spirit Nuke', 'Upon activation , Spirit Nuke scales 2.25 times off her original damage to all enemies within her range. (This will effect Air enemies , Also the ability is effected by Buff and Level). This ability does have a global cooldown.', 'Instant Damage', '480'),
(117, 'https://static.wikia.nocookie.net/allstartd/images/0/0c/StandBy_Ability_Icon.png/revision/latest?cb=20240321100222', 'StandBy_Ability_Icon.webp', 'Stanby', 'Upon activation , Falcon (Ascendance) will stop attacking until this ability is activated again. The cooldown of this ability is 10 seconds.', 'Standby', '10'),
(118, 'https://static.wikia.nocookie.net/allstartd/images/b/bf/Steal_Soul.png/revision/latest?cb=20221121031526', 'Steal_Soul.webp', 'Steal Soul', 'Upon activation of this ability , a cutscene plays. During the cutscene , all enemies on the map like Powerful 1/2 , Decelerate , Cloner , Regenerate , Elemental , and Rage (except for Air , Armored , Miniboss , and Boss enemies) turns into regular enemies.\nThis ability has a server wide cooldown , meaning you and other players cant use the ability from the rest of Demon Lords already maxed upgrade in place , you cant do the same method as The Patriot (such as spam place , upgrade , and use the ability) nor you cant use Yoshaga Kiryu (Eat The Dirt) -  Eat The Dirt ability to reset Steal Soul -  cooldown until the global cooldown expires.', 'Reveal', '480'),
(119, 'https://static.wikia.nocookie.net/allstartd/images/d/d0/Strength_Buff_Magic_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240619124010', 'Strength_Buff_Magic_Ability_Icon.webp', 'Strength Buff Magic', 'Upon activation of this ability , the damage of other units within her range increases by up to 300% , and their range increases by up to 20%. This ability lasts for 30 seconds and has a cooldown of 60 seconds.', 'Buff', '60'),
(120, 'https://static.wikia.nocookie.net/allstartd/images/3/30/JJ-Siwa_%28Furious%29%27s_String_Trap.png/revision/latest?cb=20230907073527', 'JJ-Siwa_2927s_String_Trap.webp', 'String Trap', 'Upon activation , JJ-Siwa will do 10x her displayed damage to ALL enemies IN RANGE (Example: JJ-Siwa Damage: 500K , String Trap Damage: 5M). This ability has a 90 second (1 minute and 30 seconds) cooldown , with NO global cooldown (Spammable).', 'Instant Damage / Stun', '90'),
(121, 'https://cdn2.iconfinder.com/data/icons/rpg-fantasy-game-basic-ui/512/stunningm_stun_star_numb_stupefy-512.png', 'crowned-explosion.png', 'Stun', 'Stun can either be applied when a unit attacks or through a manual ability , although the latter is much more common. Manual abilities than can stun units are commonly referred to as “timestops” (as some of them originate from JoJo’s Bizarre Adventure). Similar to freezing , you will not be able to time stop nor time rewind an enemy that is stunned. Enemies that get timestopped cannot be timestopped again for 10 seconds.', 'Stun', 'passive'),
(122, 'https://cdn.creazilla.com/cliparts/76695/sun-icon-clipart-xl.png', 'solar-time.png', 'Sunburn', 'Sunburn causes an affected enemy to take damage every 3 seconds for 21 seconds in total (7 ticks). With an additional 18% movement speed reduction that also can be stacked with already slowed enemies , which it makes 68% movement speed reduction. It also cannot be stacked with GaleSlow or WaxSlow.', 'Damage Over Time / Slow', 'on hit'),
(123, 'https://static.wikia.nocookie.net/allstartd/images/1/14/King_Of_Heroes_Form_4_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20220520012121', 'King_Of_Heroes_Form_4_Ability_Icon.webp', 'Switch Attack Patterns', 'This ability allows King Of Heroes to switch between forms that change all of his main attack attributes. You can shift as many times as you wish with very short cooldowns between shifts. Note: You can not shift forms while under the effects of Erwin -  attack buff or Merlin -  range boost. Visit the page for this unit to see what each form does and the unit -  stats when shifted.', 'Attack Change', '5'),
(124, 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSOx7axC0g8Ftf88bapKbZ5rI1rfzfHbbpE4A&s', 'images1.jpg', 'Switch Attack Patterns (Tony Stark)', 'This ability allows Tony Stark (Beyond) to switch between forms that change all of his main attack attributes. You can shift as many times as you wish with very short cooldowns between shifts. Note: You can not shift forms while under the effects of Erwin -  attack buff or Merlin -  range boost. Visit the page for this unit to see what each form does and the unit -  stats when shifted.', 'Attack Change', '5'),
(125, 'https://static.wikia.nocookie.net/allstartd/images/b/ba/Sword_Blocker.png/revision/latest/scale-to-width-down/92?cb=20220515061849', 'Sword_Blocker.webp', 'Sword Blocker', 'When Sword Blocker is activated , Saber protects base with her sheath , Avalon , and prevents enemies from walking past a certain point for 28 seconds , and if they do pass it , they get pushed back. This ability also stops time that lasts for 25 seconds , and it covers the entire map. The cooldown is 6 minutes and 40 seconds. It has global cooldown. Units trapped by this ability are unable to be attacked or affected by abilities until this ability is finished. (Although this ability does not have a global cooldown , enemies affected by this are unable to be affected by this again).', 'Base Protection', '640'),
(126, 'https://static.wikia.nocookie.net/allstartd/images/7/72/Teachings.png/revision/latest/scale-to-width-down/80?cb=20220710055129', 'Teachings.webp', 'Teachings', 'Teachings is an ability that buffs other units damage in Metallic King -  range. The buff has a duration of 40 seconds and a cooldown of 60 seconds , and has a stacking limit of 250% (making the buff 3.5x the initial damage).', 'Buff', '60'),
(127, 'https://static.wikia.nocookie.net/allstartd/images/5/53/The_Final_March_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20240206072451', 'The_Final_March_Ability_Icon.webp', 'The Final March', 'Upon activation , a short cutscene will play and Airren (Doomsday) brings about the Rumbling , summoning Colossal Giants that walk from the base to the enemy spawn. This skill does tick damage , dealing 40% of his current damage three times every second an enemy is in contact with a Colossal Giant. The Founder must be placed down on the map to use this ability , and only one The March! can be active at a time.', 'Summon', '500'),
(128, 'https://static.wikia.nocookie.net/allstartd/images/4/41/Hudron_The_Mystic_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20231215070228', 'Hudron_The_Mystic_Ability_Icon.webp', 'Tidepool', 'Tidepool is an ability with a cooldown of 60 seconds that in Hudron -  AOE range will deal 6x Hudron -  basic attack damage (scaled with buff %) to all enemies in the range.', 'Instant Damage', '60'),
(129, 'https://static.wikia.nocookie.net/allstartd/images/d/d5/Time_Acceleration_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20230929055659', 'Time_Acceleration_Ability_Icon.webp', 'Time Acceleration', 'Upon activation , Lucci will create a consumable status effect for all enemies in range. When the next DoT effect (Ex. Bleed/Burn) hits , it will deal all ticks of the DoT damage in a single hit. For example , instead of Organs (Berserker) needing 24 ticks , it will only take 1 hit to fully deal his total Rupture damage. This ability has a 1 minute GLOBAL cooldown. This ability doesnt work on Armored enemies as they are immune to status effects.', 'Special', '60'),
(130, 'https://static.wikia.nocookie.net/allstartd/images/8/8b/Time_Stop_II_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20230703083227', 'Time_Stop_II_Ability_Icon.webp', 'TimeStop II', 'When activated , he timestops all enemies in his range (even with buff) for 6.5 seconds. The cooldown of this ability is 30 seconds.', 'Stun', '30'),
(131, 'https://static.wikia.nocookie.net/allstartd/images/4/41/Untitled2.png/revision/latest/scale-to-width-down/92?cb=20220212232410', 'Untitled2.webp', 'TimeStop P4', 'TimeStop P4 is Jokato Koju -  manual ability that freezes all enemies in place for five seconds , and does not stack with other P4 TimeStops. It has a range of ~80 and a 30 second cooldown.', 'Stun', '30'),
(132, 'https://static.wikia.nocookie.net/allstartd/images/f/f0/Total_Destruction_v2_Ability_Icon.png/revision/latest?cb=20240327100719', 'Total_Destruction_v2_Ability_Icon.webp', 'Total Destruction V2', 'When activated , Esper Bro will achieve 100% Ritsu mode , collapsing the area around him. This ability deals 3.5 billion damage to all enemies in his range and permanently increases his damage by 16.8 million. This ability is a one-time use.', 'Nuke', 'infinite'),
(133, 'https://static.wikia.nocookie.net/allstartd/images/b/b1/Total_Judgement_Ability_Icon.png/revision/latest?cb=20240124003408', 'Total_Judgement_Ability_Icon.webp', 'Total Judgement', 'When activated , Frost Moon will time stop the ENTIRE map for 24 seconds and deal 110 Million damage to ALL enemies on the map. This ability has a global cooldown.', 'Golden Stun / Instant Damage', '400'),
(134, 'https://static.wikia.nocookie.net/allstartd/images/7/76/Touch_Of_Grace.png/revision/latest?cb=20231126032211', 'Touch_Of_Grace.webp', 'Touch of Grace', 'Upon activation of this ability , all enemies within her range like Powerful 1/2 , Decelerate , Regenerate , Elemental , Rage , Armored , and Steadfast (except for Air , Miniboss , and Boss enemies) turns into regular enemies. But unlike DemonLord Waifu , she cant turn Cloners into regular enemies.', 'Reveal', '180'),
(135, 'https://static.wikia.nocookie.net/allstartd/images/3/3d/Tsuku_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240411070144', 'Tsuku_Ability_Icon.webp', 'Tsuku', 'When this ability is activated , all enemies on the entire map will be timestopped for 40 seconds. Although in nature it is similar to Mysterious X (Final) and Jokato Koju (ASCENDED) , it can stack with them as it instead uses the global cooldown shared among The Patriot , Red Servant (Final) and Ex-Captain (B-Kui) -  Base protections. (Cooldown for the entire ability is 360 seconds.)\nWithin the duration of the ability , Legendary Leader (Path) applies a DOT effect similar to True Evil (Full Power) -  Decay which will reduce all enemies that are above 33% of their max HP to 33% of their max HP at a rate of 1% every 2-seconds , or 66-seconds in total without help.', 'Rewind / Damage by %', '360'),
(136, 'https://www.google.com/url?sa=i&url=https%3A%2F%2Fgame-icons.net%2Ftags%2Farrow.html&psig=AOvVaw2tWIQX62eL9YKglhhQLHjr&ust=1740010320158000&source=images&cd=vfe&opi=89978449&ved=0CBQQjRxqFwoTCKDcs9u5zosDFQAAAAAdAAAAABAE', 'fast-arrow.png', 'Typebane', 'Unhuman (Nullifier) can do 2x damage to enemies that have or originally* have a Title and can also do Piercing damage to Elemental enemies.\nUnhuman (Nullifier) can still do 2x damage to enemies that got turn to regular enemies (*)', 'Special', 'passive'),
(137, 'https://static.wikia.nocookie.net/allstartd/images/1/13/Ultimate_Time_Stop_II_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20230703083208', 'Ultimate_Time_Stop_II_Ability_Icon.webp', 'Ultimate TimeStop II', 'When activated , he timestops all enemies over the entire map , and lasts for a very long 30 seconds , while still allowing your units to attack and allowing you to skip waves. The cooldown of this ability is 500 seconds.', 'Golden Stun', '500'),
(138, 'https://static.wikia.nocookie.net/allstartd/images/8/8a/Universe_Reset_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20230929055713', 'Universe_Reset_Ability_Icon.webp', 'Universe Reset', 'Upon activation , Lucci resets ALL enemies back to the spawn (no matter where they are on the map) , but in exchange , all enemies affected by the ability return to their full HP. This ability is a ONE-TIME use.', 'Teleport', 'infinite'),
(139, 'https://static.wikia.nocookie.net/allstartd/images/0/09/Upper_Fusion_Ability_Icon.png/revision/latest/scale-to-width-down/92?cb=20231026215219', 'Upper_Fusion_Ability_Icon.webp', 'Upper Fusion', 'When you activate Upper Fusion , it will show cutscene of fusion between Anger Demon , Pleasure Demon , Joy Demon , and Grief Demon. When the cutscene end , all 4 units will be fusion into Hatred Demon with Wind Dragon deployment.', 'Special', 'infinite'),
(140, 'https://static.wikia.nocookie.net/allstartd/images/5/5f/Villian_Finisher_Ability_Icon.png/revision/latest?cb=20240622084120', 'Villian_Finisher_Ability_Icon.webp', 'Villain Finisher', 'When activated , Kogan Supa II (Alternative) will deal 500 Million damage to ALL enemies on the map. This ability is a one-time use and has an infinite global cooldown linked with Stampede (???%) -  Esper Rage.', 'Nuke', '999999'),
(141, 'https://static.wikia.nocookie.net/allstartd/images/e/e4/Waffle_Maker_Ability_Icon.png/revision/latest?cb=20240703053028', 'Waffle_Maker_Ability_Icon.webp', 'Waffle Maker', 'Upon activation , The Strongest In History kills all enemies that have 10% or lower HP.', 'Nuke by %', '999999'),
(142, 'https://static.wikia.nocookie.net/allstartd/images/0/0a/WallOfLight.png/revision/latest/scale-to-width-down/92?cb=20220619044711', 'WallOfLight.webp', 'WallOfLight', 'When activated , Fused Zamasu creates a huge purple entity , resembling a monstrous bird. This will decrease enemies HP down to 50% , but it only works if the enemy has 50% HP or above. This will only affect the enemies in his range (Including Air). The cooldown of this ability is 4 minutes and 10 seconds.', 'Damage by %', '250'),
(143, 'https://www.google.com/url?sa=i&url=https%3A%2F%2Fattackontitan.fandom.com%2Fwiki%2FWar_Hammer_Titan_%2528Anime%2529&psig=AOvVaw2UqnOTjy3LOqqLoRz8vbkQ&ust=1739968041158000&source=images&cd=vfe&opi=89978449&ved=0CBQQjRxqFwoTCMDSg5uczYsDFQAAAAAdAAAAABAE', 'Lara_Tybur_29_character_image_29.webp', 'Warhammer Giant (Bleeds)', 'Upon activation , it will apply 1 ,5x the unit -  damage in rupture to all enemies on her range. Summons a Titan with 126B.', 'Damage Over Time / Summon', '660'),
(144, 'https://cdn-icons-png.flaticon.com/512/775/775403.png', 'cobweb.png', 'Wax Slow', 'WaxSlow temporarily reduces the movement speed of the enemy hit by 85% for 35 seconds not based on gamespeed (35s on x1 , 105s on x3). It cannot stack with Slow , GaleSlow , or Sunburn.', 'Slow', 'on hit'),
(145, 'https://static.wikia.nocookie.net/allstartd/images/5/52/Killer_S_Ability_Wishes.png/revision/latest/scale-to-width-down/75?cb=20220710034436', 'Killer_S_Ability_Wishes.webp', 'Whishes', 'Killer S+ has a manual ability that gives you the opportunity to make one of 3 wishes.\n\nYou can make one of the wishes:\n\nHealing:\nAdds as much HP to the base as the Killer S+ damage at the moment. (Stack with Onwin buff)\nDeath:\nDeals 2 Million DMG to every units in his range.\nMoney:\nAdd 10 ,000 to balance. Cooldown:400s', 'Special', '400'),
(146, 'https://static.wikia.nocookie.net/allstartd/images/5/53/Wounded_Pride_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240703054024', 'Wounded_Pride_Ability_Icon.webp', 'Wounded Pride', 'Upon activation , Vegu (Ego Ascension) is buffs his overall power and adds a permanent 61 ,200 ,000 damage to his current damage. This ability also allows him to hit elementals for 50% of his damage.\nThis ability has an infinite global cooldown that shared with Evil Shade (Final) -  Dragon Absorption , And Tatsu (Rainbow Flames) -  Rainbow Flame Surge', 'Self Buff', 'infinite'),
(147, 'https://static.wikia.nocookie.net/allstartd/images/9/97/Kura_Write_Names_Ability.png/revision/latest?cb=20220520005909', 'Kura_Write_Names_Ability.webp', 'Write Names', 'When clicked , damage equal to that stated on their cards is dealt to every enemy in range.', 'Instant Damage', '500'),
(148, 'https://static.wikia.nocookie.net/allstartd/images/0/00/Yomi_Ability_Icon.png/revision/latest/scale-to-width-down/100?cb=20240411070237', 'Yomi_Ability_Icon.webp', 'Yomi', 'Upon activation , all enemies are rewinded to their position 36 seconds ago. In addition , enemies are converted into summonable clones , which retain 10% of the enemies maximum HP. Each clone summoned by Legendary Leader (Path) has a 100 ,000 ,000 ,000 (100 billion) health cap , similar to Eyezen (Final). This ability also inflicts a Black Flames nuke that deals approximately x16 his current DMG after 40 seconds. (The Black Flames will instantly deal the total damage if Lucci (Heaven) Time Acceleration is affecting the enemy.)\nThe damage from the Black Flames nuke scales with Legendary Leader (Path) -  damage.\nThe rewind from this ability is able to stack with regular rewinds , such as Julian (King of Wizards). (Cooldown for the entire ability is 840 seconds.)', 'Summon / Instant Damage', '840'),
(149, 'https://static.wikia.nocookie.net/allstartd/images/3/3c/Your_Star.png/revision/latest/scale-to-width-down/80?cb=20230516074331', 'Your_Star.webp', 'Your Star', 'Upon activation , a cutscene plays where Idol does a short performance. The ability makes every enemy currently on the map take 15% more damage from all sources for 4 minutes.', 'Buff', '600'),
(150, 'https://cdn2.iconfinder.com/data/icons/rpg-fantasy-game-basic-ui/512/item_game_pirate_chest_treasure_box_gold-512.png', 'chest.png', 'Idol Income', 'Provides from $ 160 (Start) up to $ 130 691 (Raid & Max) per wave.', 'Income', 'each wave'),
(151, 'https://cdn2.iconfinder.com/data/icons/rpg-fantasy-game-basic-ui/512/item_game_pirate_chest_treasure_box_gold-512.png', 'chest.png', 'Jeff Income', 'Provides from $ 195 (Start) up to $ 287 820 (Raid & Max) per wave.', 'Income', 'each wave');
