(1, 'Attack Change', 'Changes the characteristics of the character’s attack.'),
(2, 'Base Protection', 'Prevents mobs from crossing the base for a certain period of time'),
(3, 'Buff', 'Boost one or more statistics of characters placed around this character'),
(4, 'Critical', 'After a number of attacks : performs a more powerful attack.'),
