(12, 'Instant Damage', 'Instant damaging mobs/'),
(13, 'Nuke', 'One-time instant damaging mobs.'),
(14, 'Nuke by %', 'One-time : Inflicts damage based on mobs lives/ Reduces mobs lives to a certain percentage'),
