INSERT INTO `glossary` (`glossary_id`, `glossary_name`, `glossary_explaination`) VALUES
(1, 'Apply Preset', 'Applies a set of chosen settings to the calculation and evaluation system.'),
(2, 'Attack Change', 'Ability that changes the specs of the character’s attack.'),
(3, 'Base Healer', 'Role given to units that Restores the base\'s HP, crucial for surviving long waves.'),
(4, 'Base Protection', 'Ability that prevents mobs from crossing the base for a certain period of time.'),
(5, 'Buff', 'Ability that boost one or more statistics of characters placed around this character.'),
(6, 'Buff Strength', '% bonus applied by the main buff (Erwin, Brook, Idol, etc.). It is applied to both dot and pure hit damages.'),
(7, 'Buffer', 'Role given to units that increases the stats or abilities of nearby units.'),
(8, 'Camper', 'Role given to units that excels at holding specific positions, providing area control.'),
(9, 'Chart Order Scaling', 'The star diagram is composed of two values: the ranking in the list of characters, and the pure value of the statistic. This parameter indicates the share (in %) assigned to the ranking.'),
(10, 'Chart Scaling', 'Changes from a linear scale (1, 2, 3, 4) to a logarithmic scale (1, 10, 100, 1000) for the diagram calculation ratios.'),
(11, 'Cooldown Reset', 'Role given to units that can resets or reduces cooldowns, allowing for more frequent ability use.'),
(12, 'Critical', 'Passive ability that after a number of attacks : performs a more powerful attack.'),
(13, 'Crowd Control', 'Role given to units that specializes in controlling large groups of enemies.'),
(14, 'Damage by %', 'Ability that inflicts damage based on mob lives/ Reduces mobs lives to a certain percentage.'),
(15, 'Damage Over Time', 'Ability that inflicts damage over time (passive or active), like bleeding, burn, poison.'),
(16, 'Enchant (Strength & Weakness)', 'Considers how the unit’s enchantment type (e.g. Fire, Water, etc.) interacts with enemy weaknesses or resistances.'),
(17, 'Enchant Change', 'Passive ability that allows the unit to replace enemies enchants by the weak enchant for the unit (ONLY if it already has a enchant).'),
(18, 'Executioner', 'Role given to units that deals high damage to finish off weakened enemies efficiently. It\'s also the default role.'),
(19, 'Farming Difficulty', 'Also known as FD. Evaluates how hard it is to obtain or evolve a unit, including materials, time, and event availability.'),
(20, 'Gamemode', 'Filters or adjusts stats based on the game mode (e.g., Raid, Infinite, Placement only, etc.), as some units perform better in certain modes.'),
(21, 'Golden Stun', 'Ability that blocks the advance of mobs for a long period of time. Cannot be spammed.'),
(22, 'Heal', 'Ability that restores life to the base/ Increases the life capacity of the base.'),
(23, 'Import Preset', 'Loads a previously saved preset (by its given ID or name) to restore your custom settings.'),
(24, 'Importance AoE Type', 'Controls how much the Area of Effect type (Circle, Cone, Line, etc.) impacts the unit’s range ranking.'),
(25, 'Income', 'Ability that makes money.'),
(26, 'Instant Damage', 'Ability that does instant damage to mobs.'),
(27, 'Investment', 'Role give to units that are really expensive to place but rewarding in high start dps output.'),
(28, 'Leader Buff', 'Indicates the percentage of damage attributed to all characters in a single category (from the first unit of the team).'),
(29, 'Leader Cost Economy', 'Indicates the cost reduction of characters in a single category (from the first unit of the team).'),
(30, 'Leader DoT Buff', 'Indicates how much Damage-over-Time (burn, bleed, etc.) boost is granted by unit in the leader slot.'),
(31, 'Max Placement', 'Refers to the number of times a unit can be placed on the map at once.'),
(32, 'Mob Health Reducer', 'Role given to units that divides by a certain % the health of mobs, making them easier to defeat.'),
(34, 'Mobility Control', 'Role given to units that manipulates enemy movement or stunning, controlling the battlefield. It\'s also the name given to abilities that can manipulates enemy movement or placement.'),
(35, 'Money Unit', 'Role given to units that generates additional cash each wave to support expensive strategies.'),
(36, 'Nuke', 'Ability that does one-time instant damage to mobs.'),
(37, 'Nuke by %', 'Ability that  does one-time damage based on mobs lives or that reduces mobs health to a certain percentage.'),
(38, 'Nuker', 'Role give to units that delivers massive burst damage, often with infinite cooldowns.'),
(39, 'Raging', 'Passive ability that increases the damage of the character each wave.'),
(40, 'Reveal', 'Ability that removes some attributes from mobs.'),
(41, 'Revealer', 'Role given to units that removes title to enemies, allowing units to target them, and remove their abilities.'),
(42, 'Rewind', 'Ability that drives back the mobs.'),
(43, 'Role', 'Describes the unit’s primary function — such as DPS, support, debuffer, farm, etc.'),
(44, 'Save Preset', 'Saves your current settings/filters to be reused later. Helpful for switching between playstyles or gamemodes. You must remember the ID that will be given to you'),
(45, 'Self Buff', 'Ability that allows an unit to boost itself.'),
(46, 'Settings', 'Refers to all the customizable options in the ASTD ranking/chart system. Allows you to define what matters most to you.'),
(47, 'Slow', 'Role given to units that reduces the speed of enemies, giving more time to attack. Also, ability that slows the enemies movement.'),
(48, 'Solo', 'Role given to units that can barely solo certain gamemodes.'),
(49, 'Special', 'Special ability that cannot be classified.'),
(50, 'Special Buffer', 'Role given to units that provides unique or niche buffs that can significantly impact certain strategies (maybe).'),
(51, 'Special Damage Boost', 'Includes unique effects like bleed, burn, poison, freeze, etc., and how much bonus damage they contribute overall.'),
(52, 'Standby', 'Ability that pauses the character.'),
(53, 'Starter', 'Role given to units that strong early game units with low cost, perfect for initial waves.'),
(54, 'Stun', 'Ability that blocks the mobs advance for a long period of time. Can be spammed.'),
(55, 'Summon', 'Ability that spawns mobs on your side of the path. Inflict damage on mobs.'),
(56, 'Summonner', 'Role given to units that spawns mobs on the track to assist in combat.'),
(57, 'Target', 'Indicates the targeting options a unit has — e.g. Air, Ground, Both, Air-only, etc.'),
(58, 'Teleport', 'Ability that teleports the mobs back.'),
(59, 'Trap', 'Ability that spawns laying traps that deals damage.'),
(60, 'Unit Level', 'Defines the current level of the unit, which affects its base stats. Usually assumed to be max level for calculations.'),
(61, 'Units Deployer', 'Role given to units that spawns additional units to assist in combat.'),
(62, 'Upgrade Progression', 'Describes how quickly and efficiently a unit gains power as you upgrade it. Units with strong early upgrades are often favored.'),
(63, 'Worthiness', 'Define how much dps the unit deals per $ of investment.'),
(64, 'Progression', 'Relevance of the cost/dps increase of the different levels of upgrades.');
